import crypto from 'crypto';
import { db } from '../../db';
import { logger } from '../../utils/logger';
import { open, seal, SecretBoxError } from '../../utils/secretBox';

// ─────────────────────────────────────────────────────────────────────────────
// Shared key of the scanner API (docs/P3-PLAN.md §9.1, M10): 32 random bytes,
// sealed with secretBox('scanner') in app_config `scanner.key`, generated by
// the first deployment (scannerInfra.ensure) and passed to the container as
// SCAND_KEY. A key that cannot be unsealed (SESSION_SECRET rotated) is
// replaced at the next deployment (the spec hash changes → recreation).
// ─────────────────────────────────────────────────────────────────────────────

export const SCANNER_KEY_CONFIG = 'scanner.key';

let cached: string | null = null;

/** The key, null when never generated or unreadable. Never throws for a sealed-value problem. */
export async function readScannerKey(): Promise<string | null> {
  if (cached) return cached;
  const row = await db('app_config').where({ key: SCANNER_KEY_CONFIG }).first('value') as { value: string } | undefined;
  if (!row?.value) return null;
  try {
    cached = open('scanner', row.value);
    return cached;
  } catch (err) {
    if (err instanceof SecretBoxError) {
      logger.warn('scanner: the shared key cannot be unsealed (SESSION_SECRET changed?): redeploy the scanner component');
      return null;
    }
    throw err;
  }
}

/** Existing key, or a fresh random one (sealed). */
export async function ensureScannerKey(): Promise<string> {
  const existing = await readScannerKey();
  if (existing) return existing;
  const key = crypto.randomBytes(32).toString('base64url');
  await db('app_config').insert({ key: SCANNER_KEY_CONFIG, value: seal('scanner', key) }).onConflict('key').merge();
  cached = key;
  return key;
}

/** Tests / after a direct app_config write. */
export function invalidateScannerKey(): void {
  cached = null;
}
